import{_ as t,o,c as s,a3 as e}from"./chunks/framework.qCVWde4n.js";const g=JSON.parse('{"title":"Mod 页：管理已装 Mod","description":"","frontmatter":{},"headers":[],"relativePath":"use/mods-page.md","filePath":"use/mods-page.md","lastUpdated":1791133906000}'),d={name:"use/mods-page.md"};function n(l,a,r,i,p,c){return o(),s("div",null,[...a[0]||(a[0]=[e(`<h1 id="mod-页-管理已装-mod" tabindex="-1">Mod 页：管理已装 Mod <a class="header-anchor" href="#mod-页-管理已装-mod" aria-label="Permalink to &quot;Mod 页：管理已装 Mod&quot;">​</a></h1><p><strong>已装 Mod 的总控台。</strong> 列出、禁用、启用、删除、分享，都在这一页。</p><h2 id="页面上有什么" tabindex="-1">页面上有什么 <a class="header-anchor" href="#页面上有什么" aria-label="Permalink to &quot;页面上有什么&quot;">​</a></h2><p>从上到下：</p><ol><li><strong>冲突告警横幅</strong>（如果有冲突才显示）</li><li><strong>Mod 列表</strong> —— 每个 Mod 一行/一块</li><li><strong>模型自检结果</strong>（页面底部）</li><li><strong>重置整个 Mod 系统</strong>（页面底部）</li></ol><h2 id="mod-列表" tabindex="-1">Mod 列表 <a class="header-anchor" href="#mod-列表" aria-label="Permalink to &quot;Mod 列表&quot;">​</a></h2><p>每个 Mod 显示：</p><table tabindex="0"><thead><tr><th>显示项</th><th>来源</th></tr></thead><tbody><tr><td><strong>名字</strong></td><td>mod.json 里的 <code>modName</code></td></tr><tr><td><strong>作者</strong></td><td>mod.json 里的 <code>author</code></td></tr><tr><td><strong>版本</strong></td><td>mod.json 里的 <code>version</code></td></tr><tr><td><strong>来源文件夹</strong></td><td>磁盘上的目录名</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">名字和文件夹名可能不同</p><p>框架显示的是 <code>mod.json</code> 里的 <code>modName</code>（你写什么就显示什么）。</p><p><strong>文件夹名只用于管理</strong>（比如禁用时会生成对应的 <code>_disabled.txt</code>）。</p><p>所以文件夹用英文、<code>modName</code> 用中文，是完全正常的。</p></div><h2 id="冲突告警横幅" tabindex="-1">冲突告警横幅 <a class="header-anchor" href="#冲突告警横幅" aria-label="Permalink to &quot;冲突告警横幅&quot;">​</a></h2><p>如果检测到 Mod 之间的冲突，页面顶部会出现一条横幅：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>检测到 3 处 Mod 间重名冲突</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="tip custom-block"><p class="custom-block-title">冲突不代表出错</p><p><strong>冲突是「可预期的正常现象」，不是 bug。</strong></p><p>当两个 Mod 改了同一个参数，或者定义了同名的舰级/编队时，就会出现冲突。框架的处理是：</p><ul><li><strong>记一条告警</strong></li><li><strong>后加载的覆盖先加载的</strong></li><li><strong>游戏照常运行</strong></li></ul><p>所以看到冲突不用慌，去 <a href="/AtlanticFleetSite/docs/use/log-page">日志页</a> 筛「告警」看具体是哪些。</p><p>详细排查见 <a href="/AtlanticFleetSite/docs/use/conflicts">Mod 冲突排查</a>。</p></div><h2 id="禁用-启用" tabindex="-1">禁用 / 启用 <a class="header-anchor" href="#禁用-启用" aria-label="Permalink to &quot;禁用 / 启用&quot;">​</a></h2><h3 id="禁用" tabindex="-1">禁用 <a class="header-anchor" href="#禁用" aria-label="Permalink to &quot;禁用&quot;">​</a></h3><p>点「禁用」按钮 → 这个 Mod <strong>不再加载</strong>，但<strong>文件还在</strong>。</p><p>实现方式是写一个标记文件（<code>&lt;文件夹名&gt;_disabled.txt</code>）。</p><div class="tip custom-block"><p class="custom-block-title">为什么用标记文件而不是删掉</p><p>因为<strong>可以随时启用回来</strong>。</p><p>如果你只是想临时排除某个 Mod 的影响（比如排查问题），禁用比删除安全得多。</p></div><h3 id="启用" tabindex="-1">启用 <a class="header-anchor" href="#启用" aria-label="Permalink to &quot;启用&quot;">​</a></h3><p>点「启用」→ 删掉标记文件 → 下次启动又会加载它。</p><h3 id="生效时机" tabindex="-1">生效时机 <a class="header-anchor" href="#生效时机" aria-label="Permalink to &quot;生效时机&quot;">​</a></h3><p>和参数一样，<strong>必须重开游戏</strong>。</p><h2 id="删除" tabindex="-1">删除 <a class="header-anchor" href="#删除" aria-label="Permalink to &quot;删除&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">两段确认操作</p><p>点一次 → 进入确认状态 再点一次 → 真的删除</p><p><strong>而且切页或收起面板时，确认状态会自动清零</strong> —— 防止残留的确认状态被误点。</p></div><p>删除 = <strong>真的删掉磁盘上的 Mod 文件夹</strong>（不是禁用）。</p><div class="warning custom-block"><p class="custom-block-title">删除不可撤销</p><p>删了就没了。如果你可能还会用到，<strong>用禁用</strong>。</p></div><h2 id="分享" tabindex="-1">分享 <a class="header-anchor" href="#分享" aria-label="Permalink to &quot;分享&quot;">​</a></h2><p>每个 Mod 后面有分享按钮：</p><p>点「分享」→ 生成该 Mod 的分享码 → <strong>自动复制到剪贴板</strong> → 粘贴到任意聊天窗口发给别人。</p><div class="tip custom-block"><p class="custom-block-title">分享码就是那个 Mod 的 mod.json</p><p>别人拿到后，在「参数」页粘贴导入即可。</p><p>详见 <a href="/AtlanticFleetSite/docs/features/sharecode">Mod 分享码</a>。</p></div><h2 id="模型自检" tabindex="-1">模型自检 <a class="header-anchor" href="#模型自检" aria-label="Permalink to &quot;模型自检&quot;">​</a></h2><p>页面底部会列出<strong>所有已登记的自制模型包</strong>的自检结果：</p><table tabindex="0"><thead><tr><th>检查项</th><th>含义</th></tr></thead><tbody><tr><td><strong>别名</strong></td><td>包的名字（= <code>.unity3d</code> 文件名）</td></tr><tr><td><strong>文件在不在</strong></td><td>磁盘上能不能找到</td></tr><tr><td><strong>是否已加载</strong></td><td>框架有没有成功加载它</td></tr><tr><td><strong>大小</strong></td><td>字节数</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">这个自检能解决什么</p><p>自制模型最容易出问题（压缩方式错、平台错、资产名错），而且出错了表现是「船长得不对」或「船看不见」，很难判断原因。</p><p>有这个自检清单，你能立刻看出：</p><ul><li>文件<strong>根本没被找到</strong> → 路径或文件名问题</li><li>文件在但<strong>没加载</strong> → 包本身有问题（压缩/平台）</li></ul></div><p>详见 <a href="/AtlanticFleetSite/docs/features/models">自制模型</a>。</p><h2 id="重置整个-mod-系统" tabindex="-1">重置整个 Mod 系统 <a class="header-anchor" href="#重置整个-mod-系统" aria-label="Permalink to &quot;重置整个 Mod 系统&quot;">​</a></h2><p>页面底部的最后一项。</p><div class="danger custom-block"><p class="custom-block-title">两段确认</p><p>和删除一样，点两次才生效。</p></div><p>它会把框架的 Mod 状态<strong>整体重置</strong>，但<strong>保留你自己的自制 Mod</strong>。</p><p>适合场景：框架配置乱了、想回到初始状态，但不想丢自己做的 Mod。</p><h2 id="一个典型排查流程" tabindex="-1">一个典型排查流程 <a class="header-anchor" href="#一个典型排查流程" aria-label="Permalink to &quot;一个典型排查流程&quot;">​</a></h2><p>装上 Mod 后游戏有异常，用这一页排查：</p><div class="language-mermaid vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A[&quot;游戏有异常&quot;] --&gt; B[&quot;Mod 页&lt;br/&gt;看冲突横幅&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B --&gt;|有冲突| C[&quot;日志页筛告警&lt;br/&gt;看是哪两个 Mod&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B --&gt;|没冲突| D[&quot;逐个禁用 Mod&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    D --&gt; E[&quot;每次禁用后重开&lt;br/&gt;看问题还在不在&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    E --&gt;|问题消失| F[&quot;找到问题 Mod&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    E --&gt;|还在| G[&quot;不是 Mod 引起的&lt;br/&gt;查其他地方&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C --&gt; D</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><div class="tip custom-block"><p class="custom-block-title">二分法更快</p><p>如果装了很多 Mod，不用一个一个试：</p><ol><li>先禁用<strong>一半</strong></li><li>重开看问题在不在</li><li>在的那一半再切一半</li></ol><p>几轮就能锁定问题 Mod。</p></div><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="mod-列表里没有我装的-mod" tabindex="-1">Mod 列表里没有我装的 Mod <a class="header-anchor" href="#mod-列表里没有我装的-mod" aria-label="Permalink to &quot;Mod 列表里没有我装的 Mod&quot;">​</a></h3><ol><li><strong>重开游戏了吗</strong></li><li><strong>文件位置对不对</strong> —— 必须是 <code>mods/&lt;文件夹&gt;/mod.json</code>，不能直接丢在 <code>mods/</code></li><li><strong>文件名对不对</strong> —— 必须是 <code>mod.json</code></li><li><strong>看日志页</strong> —— 会记录解析失败的原因</li></ol><h3 id="显示的名字是文件夹名不是-modname" tabindex="-1">显示的名字是文件夹名不是 modName <a class="header-anchor" href="#显示的名字是文件夹名不是-modname" aria-label="Permalink to &quot;显示的名字是文件夹名不是 modName&quot;">​</a></h3><p>说明 <code>mod.json</code> 里的 <code>modName</code> 字段为空或没解析成功。检查文件格式（比如少了逗号、多了注释符号）。</p><h3 id="禁用了但还在生效" tabindex="-1">禁用了但还在生效 <a class="header-anchor" href="#禁用了但还在生效" aria-label="Permalink to &quot;禁用了但还在生效&quot;">​</a></h3><p><strong>重开游戏了吗？</strong> 禁用需要重启才生效。</p><p>如果重开还在，去「Mod」页确认标记文件真的写进去了（或者直接删除那个 Mod）。</p><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li>冲突怎么处理 → <a href="/AtlanticFleetSite/docs/use/conflicts">Mod 冲突排查</a></li><li>怎么装 Mod → <a href="/AtlanticFleetSite/docs/deploy/install-mod">安装 Mod 的三种方式</a></li><li>日志怎么看 → <a href="/AtlanticFleetSite/docs/use/log-page">日志页：自查问题</a></li></ul>`,54)])])}const u=t(d,[["render",n]]);export{g as __pageData,u as default};
